FILE = "miss-universe-2026-jennifer-barreto.html"
TITLE = "Jennifer Barreto wins Miss Universe 2026 at home, the first mother to take the crown"
TAG = "The Wrap"
H1 = "Jennifer Barreto wins Miss Universe 2026 at home, the first mother to take the crown"
DEK = "Puerto Rico's own won the 75th crown in San Juan. Africa sent five women into the Top 30, with DR Congo's Jessi Kalambayi going furthest in the Top 12, while Kenya's Jean Ojiro didn't place."
META = "The Wrap · Global · 25 Nov 2026 · 4 min read"
LEAD = ("img/wr-miss-universe-2026.jpg", "Miss Universe 2026 Jennifer Barreto on stage in San Juan", "@justjared / Instagram")

BODY = [
("p", "Puerto Rico hosted the 75th Miss Universe, and Puerto Rico won it. Jennifer Barreto was crowned Miss Universe 2026 on Tuesday night, 24 November, at the Coliseo de Puerto Rico José Miguel Agrelot in San Juan, early Wednesday morning in Kenya. The outgoing queen, Mexico's Fátima Bosch, put the crown on her head in front of a home crowd."),
("p", "The win makes Barreto the first mother to be crowned Miss Universe, and the first married woman. Her daughter, Penélope, is seven, and her husband is Jean Carlos Barreto. Mothers have only been allowed to compete at Miss Universe since 2023, so this is very recent history."),
("p", "It's Puerto Rico's sixth Miss Universe title. The first five went to Marisol Malaret (1970), Deborah Carthy-Deu (1985), Dayanara Torres (1993), Denise Quiñones (2001) and Zuleyka Rivera (2006). The 20-year wait since then ended on home ground, which has happened for Puerto Rico once before. Quiñones won in 2001 when the pageant was held in Bayamón."),
("h2", "", "Who ", "she is"),
("p", "Barreto is 27 and represented the town of San Sebastián at the national pageant. She has a bachelor's degree in research psychology and master's degrees in psychology and clinical social work. What makes her run stand out is how new she is to pageants. Before Miss Universe Puerto Rico in June, she had never competed in one. Five months later she was Miss Universe."),
("p", "When she won the national title, she said she wanted to use her reign to talk about mental health and show that being a mother doesn't hold a woman back from her goals."),
("h2", "", "The final five, and ", "the question"),
("facts", [("Miss Universe 2026", "Jennifer Barreto, Puerto Rico"), ("1st runner-up", "Melissa Núñez, Dominican Republic"), ("2nd runner-up", "Clara Vegas, Venezuela"), ("3rd runner-up", "Bea Millan-Windorski, Philippines"), ("4th runner-up", "Georgia Waddington, New Zealand")]),
("p", "All five got the same final question: what does the world need most from its leaders right now? Barreto's answer was about listening. Leaders make a lasting difference, she said, when they hear what their communities actually need and shape their plans around it."),
("h2", "", "The ", "Top 12"),
("p", "Twelve women made it through the swimsuit round to evening gown: Chile's Dominga López, the Dominican Republic's Melissa Núñez, the United States' Justus Kelley, New Zealand's Georgia Waddington, Cuba's Mia Dio, Puerto Rico's Jennifer Barreto, the Philippines' Bea Millan-Windorski, Colombia's María Alejandra López, Nicaragua's Jasmine Blandford, Venezuela's Clara Vegas, DR Congo's Jessi Kalambayi and France's Garance Authié."),
("h2", "", "The ", "Top 30"),
("p", "The first cut took the field from 116 contestants down to 30. Besides the Top 12, the semifinalists were Brazil, India, the Netherlands, Turks and Caicos, Peru, Serbia, Curaçao, Israel, Ecuador, Tanzania, Mexico, Guinea, Ukraine, Panama, Costa Rica, Uganda, Ethiopia and Belgium."),
("p", "One of the 30 places went to a fan vote. Ecuador's Dalia Bucaram got it as the People's Choice."),
("h2", "", "How Africa ", "did"),
("p", "Five African contestants made the Top 30."),
("p", "<b>Jessi Kalambayi, DR Congo:</b> She got furthest of the African contestants, reaching the Top 12. She's 28, from Kinshasa, and has done this before. She was Miss Colorado USA 2024 and made the Top 10 at Miss USA that year."),
("p", "<b>Elizabeth Makune, Tanzania:</b> Makune won Miss Tanzania in 2018 and represented the country at Miss World. Eight years later she came back to pageants as Miss Universe Tanzania 2026."),
("p", "<b>Mitchelle Daka, Uganda:</b> This was Uganda's first-ever year at Miss Universe, and she made the Top 30 on her first try."),
("p", "<b>Bruk Belete, Ethiopia:</b> Ethiopia was back at Miss Universe this year after time away."),
("p", "<b>Justine Kamara, Guinea.</b>"),
("p", "None of them reached the final five, a year after Côte d'Ivoire's Olivia Yacé made the Top 5 in 2025."),
("h2", "", "Kenya's ", "run"),
("p", "Kenya was also back this year. Jean Ojiro, a model, media personality and content creator, was crowned Miss Universe Kenya on 25 July at Emara Ole-Sereni in Nairobi, picked from more than 500 hopefuls. She went to Puerto Rico campaigning against femicide but didn't make the Top 30. Nigeria's Danielle Adewusi and South Africa's Bajabulise Thela didn't place either."),
("h2", "", "The night ", "itself"),
("p", "The show was hosted by Miss Universe 2022 R'Bonney Gabriel and Mario Lopez, with commentary from Zuri Hall and Dayanara Torres, Puerto Rico's Miss Universe 1993. Barreto takes home the new 75th-anniversary crown, “The Radiance of an Eternal Legacy,” designed by George Wittels."),
("p", "Barreto now moves into her reign as Miss Universe 2026, a year that starts at home."),
]

